import{z as o,x as A,o as t,c as l,q as n,j as i,D as E,d as r,s as c,S as d,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"etcd 案例走读","description":"","frontmatter":{"title":"etcd 案例走读","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/con-etcd-case.md","filePath":"cs/con-etcd-case.md","lastUpdated":1791413859000}'),B={name:"cs/con-etcd-case.md"};function p(D,e,f,h,m,u){const s=A("Mermaid");return t(),l("div",null,[e[2]||(e[2]=n('<h1 id="etcd-案例走读" tabindex="-1">etcd 案例走读 <a class="header-anchor" href="#etcd-案例走读" aria-label="Permalink to &quot;etcd 案例走读&quot;">​</a></h1><div class="epigraph"><p>etcd 的价值不在它跑的是 Raft，而在它把 Raft 装配成一个能被整个 Kubernetes 依赖的产品：修订号、租约、watch、配额——每一样都是共识之上的最小合同。</p><footer>—— 据 etcd 官方文档整理；定位与对照另见 Burrows, The Chubby lock service, OSDI 2006</footer></div><p><a href="/cs/con-consensus-rsm">上一课</a>拆了共识引擎与状态机的接缝；本课把这份合同读进一个真实产品。主干课的 <a href="/cs/etcd-chubby">etcd / Chubby</a> 已给过定位：共识做成锁与配置 API；本课下到 etcd 的具体机制——MVCC 修订号、两档读、租约、压缩与配额——以及部署时真正会踩到的参数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kubernetes 把集群全部状态放在 etcd 上：API Server 靠 watch 订阅每次变更，节点心跳靠租约维持，选主与协调靠事务。每条需求都要映射到共识语义：watch 要求「事件按提交顺序可重放」；租约要求「领导者换届时租约不复活」；读要求两档清晰标价——线性一致与串行。映射错了就是事故：拿串行读做选主判断、把 etcd 当消息队列塞大 value、从不规划压缩与配额直到 backend 写满、整个集群跟着只读。</p><p><span class="marginnote">术语翻译：MVCC（多版本并发控制）就是每次修改不覆盖旧值，而是追加一个带版本号的新版本。etcd 的 revision 是全局递增的版本号——第 100 次提交就得到 revision 100；watch 客户端只要说「我从 revision 97 开始听」，就能按提交顺序补齐之后的全部变更。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是合同走读而不是源码走读：把 etcd 的每个对外机制——修订号、读的两档、租约、压缩与配额——映射回前几课的共识语义，问它消费的是哪条保证、对外暴露的是哪个全序性质；机制读完再算部署账，把默认参数当合同条款逐条对价。走读顺序按 API 面排，不按模块目录排。</p><h3 id="修订号-共识全序的对外暴露" tabindex="-1">修订号：共识全序的对外暴露 <a class="header-anchor" href="#修订号-共识全序的对外暴露" aria-label="Permalink to &quot;修订号：共识全序的对外暴露&quot;">​</a></h3><p>四件套走读。MVCC 与 revision：每笔提交分配全局递增 revision，键的每次修改留历史，range 可按 mod_revision 过滤——前几课里共识给定的全序，在这里直接变成 API：watch 就是按 revision 重放，客户端可以问「从我上次看到的 revision 之后给我增量」。读两档：默认线性一致，内部走 ReadIndex——领导者先确认任期再取 commitIndex，等状态机追上后应答，正是应用管线课的排队语义；声明 <code>Serializable</code> 才跳过确认，换更低延迟与可能读旧值。租约：TTL 绑定在 raft 时钟上，keepalive 续约；节点失联、租约过期，挂在上面的 key 自动删除——锁的过期与 fencing 号（lease ID）从这里来。压缩与配额：revision 历史用 compact 截断，删键只是墓碑；compact 后空间不还给文件系统，还要 defrag；backend 配额默认 2 GiB，写满进入只读。</p><p><span class="marginnote">etcd 的默认值是一张部署账：选举超时 1000 ms、心跳 100 ms、单请求上限约 1.5 MiB、backend 配额 2 GiB。磁盘 fsync 变慢先表现为选举超时与写延迟尖刺——把慢盘当网络问题查，是 etcd 故障诊断最常见的第一错。</span></p>',11)),(t(),i(d,null,{default:E(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20RAFT%5B%22Raft%20%E6%97%A5%E5%BF%97%EF%BC%9A%E5%A4%9A%E6%95%B0%E6%B4%BE%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20RAFT%20--%3E%20MVCC%5B%22%E7%8A%B6%E6%80%81%E6%9C%BA%E5%BA%94%E7%94%A8%EF%BC%9A%E5%88%86%E9%85%8D%E6%96%B0%20revision%22%5D%0A%20%20MVCC%20--%3E%20HIS%5B%22%E5%8E%86%E5%8F%B2%E7%89%88%E6%9C%AC%E4%B8%8E%E5%A2%93%E7%A2%91%22%5D%0A%20%20HIS%20--%3E%20CMP%5B%22%E5%AE%9A%E6%9C%9F%20compact%20%E5%8A%A0%20defrag%22%5D%0A%20%20W2%5B%22%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20MODE%7B%22%E6%A1%A3%E4%BD%8D%EF%BC%9F%22%7D%0A%20%20MODE%20--%3E%7C%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%7C%20RI%5B%22ReadIndex%EF%BC%9A%E7%A1%AE%E8%AE%A4%E4%BB%BB%E6%9C%9F%EF%BC%8C%E7%AD%89%20apply%20%E8%BF%BD%E4%B8%8A%22%5D%0A%20%20MODE%20--%3E%7C%E4%B8%B2%E8%A1%8C%7C%20SER%5B%22%E7%9B%B4%E6%8E%A5%E8%AF%BB%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"部署账接着算：成员取奇数（3 或 5），多数派决定写可用性；写吞吐被一轮多数派 fsync 限住，普通 SSD 上是千级写每秒的量级——etcd 是协调面不是数据面，大 value 外置、大事务拆批。诊断顺序固定：先看磁盘 fsync 延迟（WAL 落盘在关键路径上），再看网络，再调心跳与选举参数——高延迟盘上要调大选举超时，否则正常的提交延迟就会触发重选。与 Chubby 对照着读：会话对应租约、sequencer 对应 lease ID 的 fencing、文件对应 key——主干课那张对照表在这里逐项落到参数上。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：3 成员集群的多数派是 2——宕 1 台还能写，宕 2 台就失去写能力；5 成员的多数派是 3，能容忍 2 台宕机。成员取奇数是因为偶数并不合算：4 成员和 3 成员一样只能容忍 1 台故障（要凑 3 台多数派），却多养一台的成本。")],-1)),(t(),i(d,null,{default:E(()=>[c(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20GROW%5B%22%E5%86%99%E5%85%A5%E4%B8%8E%E5%8E%86%E5%8F%B2%E6%8C%81%E7%BB%AD%E5%A2%9E%E9%95%BF%22%5D%20--%3E%20Q%5B%22backend%20%E8%A7%A6%E5%88%B0%E9%85%8D%E9%A2%9D%202%20GiB%22%5D%0A%20%20Q%20--%3E%20RO%5B%22etcd%20%E8%BF%9B%E5%85%A5%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20RO%20--%3E%20K8S%5B%22Kubernetes%20%E5%85%A8%E9%83%A8%E5%86%99%E8%A2%AB%E6%8B%92%22%5D%0A%20%20K8S%20--%3E%20REC%5B%22%E6%81%A2%E5%A4%8D%3A%20compact%20%E6%88%AA%E6%96%AD%E5%8E%86%E5%8F%B2%22%5D%0A%20%20REC%20--%3E%20DEF%5B%22defrag%20%E5%BD%92%E8%BF%98%E7%A9%BA%E9%97%B4%22%5D%0A%20%20DEF%20--%3E%20RAISE%5B%22%E5%BF%85%E8%A6%81%E6%97%B6%E8%B0%83%E9%AB%98%E9%85%8D%E9%A2%9D%22%5D%0A%20%20RAISE%20--%3E%20RW%5B%22%E6%81%A2%E5%A4%8D%E5%8F%AF%E5%86%99%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p><span class="marginnote">常见误区：把 etcd 当通用数据库用——塞大 value、跑大范围扫描。它是协调面不是数据面：每个键值都要过 Raft 多数派确认与 fsync，单请求上限约 1.5 MiB。大对象应放对象存储、etcd 里只存指针；否则一个慢写就能拖住整个 Kubernetes。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不逐行走读源码——锁与协程调度不属于语义层；也不把 etcd 用成数据库或队列，容量与吞吐的账已经给出。Chubby 的会话机制对照但不展开；Raft 内部细节回第一课，不重述。诊断还有一条要钉死：「etcd 满了」不是单纯容量事故——配额触发只读是设计行为，恢复要 compact 加 defrag 加提额，期间 API Server 的所有写都被拒，这是「共识之上的合同」里最贵的一条。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>revision 把共识的全序直接暴露为 API；watch 是按 revision 的重放。</li><li>默认读是线性一致（ReadIndex）；<code>Serializable</code> 是显式降档，不是默认。</li><li>租约绑定 raft 时钟：过期删 key，lease ID 当 fencing。</li><li>compact 管历史、defrag 管空间、配额管生死——三者要一起规划。</li><li>部署账：3 或 5 成员、fsync 在关键路径、协调面不承载数据面流量。</li><li>出处：etcd 官方文档（默认参数与线性一致读）；Burrows, OSDI 2006；Ongaro and Ousterhout, ATC 2014。</li></ul>',5))])}const F=o(B,[["render",p]]);export{b as __pageData,F as default};
